import { createFakeLifecycleProvider } from './fake-lifecycle-provider.mjs';

export const VIDEO_BINDING = 'sha256:' + 'd'.repeat(64);
export const VIDEO_MODEL = 'video-fixture::text-video';
export const VIDEO_WEBM = Buffer.from('', 'base64');
export const VIDEO_MP4 = Buffer.from('', 'base64');
export function videoFlowFixture({ unknown = false, beforeSubmit, mediaType = 'video/mp4', bytes = VIDEO_MP4 } = {}) {
  const fake = createFakeLifecycleProvider({ id: 'video-fixture', capabilities: ['video'],
    submitSteps: Array.from({ length: 30 }, () => async (input, context) => {
      await beforeSubmit?.(input, context);
      return unknown ? { kind: 'acceptance_unknown', error: { category: 'network', stage: 'response', acceptance: 'unknown', message: 'controlled unknown' } }
        : { kind: 'accepted', remoteTaskId: 'original-video-task' };
    }),
    pollSteps: Array.from({ length: 30 }, () => ({ kind: 'succeeded',
      artifacts: [{ kind: 'inline-base64', data: bytes.toString('base64'), mediaType }] })) });
  return { adapter: fake.adapter, calls: fake.calls,
    resolveVideoCandidates({ modelRef, signal }) {
      signal.throwIfAborted();
      if (modelRef !== VIDEO_MODEL) throw Error('unexpected video model');
      return [{ adapter: fake.adapter, model: modelRef, providerBinding: VIDEO_BINDING, selectionReason: 'explicit' }];
    },
    resolveTaskAdapter(task) {
      if (task.providerBinding !== VIDEO_BINDING || task.modelRef !== VIDEO_MODEL) throw Error('video binding drift');
      return fake.adapter;
    }
  };
}
